namespace WinDiag.Core.Knowledge;

public static partial class Glossary
{
    /// <summary>Versão em inglês dos verbetes (título e texto), por chave.</summary>
    private static Dictionary<string, (string Title, string Text)> BuildEnglish() => new(StringComparer.OrdinalIgnoreCase)
    {
        ["processador"] = ("Processor (CPU)", "The processor is the PC's \"brain\": it runs the game logic and physics and prepares frames for the graphics card. More cores and higher clocks help in modern games, but what matters most is how it pairs with the graphics card. For current games, 6 cores or more is a good starting point."),
        ["memoria"] = ("Memory (RAM)", "RAM holds what the game and Windows are using right now. If it runs out, Windows falls back to the disk and the game stutters. For current games, 16 GB is the comfortable minimum and 32 GB gives headroom with other programs open."),
        ["memoria_ram"] = ("RAM and speed", "Besides the amount, the speed of the RAM and whether it runs in two channels matter. Fast memory in dual channel keeps the processor better fed, which helps mainly processors with few cores. The good value is the maximum speed the processor accepts."),
        ["placa_de_video"] = ("Graphics card (GPU)", "The graphics card draws the game's images. It is the component that weighs most on FPS. What matters is the model, the amount of video memory and whether the driver is up to date."),
        ["monitores"] = ("Monitors", "The monitor defines the resolution and how many times per second the image is refreshed. A 144 Hz monitor only shows 144 frames per second if it is set to that rate in Windows. With two monitors, different refresh rates can cause small stutters."),
        ["armazenamento"] = ("Storage (disks)", "This is where Windows and the games live. SSD and NVMe are much faster than HDD, which shortens loading screens and reduces stutter. Ideally Windows and games are on an SSD, with at least 20% free space."),
        ["disco"] = ("Disk", "Each physical disk in the PC appears in a block with model, type (HDD, SSD, NVMe), capacity, temperature and health. Health comes from Windows and from the disk's own S.M.A.R.T. data. Healthy and below about 55 °C is expected."),
        ["particoes"] = ("Partitions and volumes", "These are the drives you see in Windows, such as C: and D:. Each one shows how much space is free. Keep at least 10% free, and 20% on an SSD, so the disk does not slow down."),
        ["steam_bibliotecas"] = ("Steam libraries", "These are the folders where Steam installs games. The app shows which disk each one is on. Games on an SSD load faster and stutter less than games on an HDD."),
        ["sistema"] = ("System", "Gathers data about Windows, the motherboard and BIOS, and the power plan. Several settings that affect game smoothness come from here."),
        ["placa_mae_bios"] = ("Motherboard and BIOS", "The motherboard connects all the parts of the PC, and the BIOS is its program that defines how the parts work. Several gaming improvements, such as XMP and Resizable BAR, are turned on in the BIOS. Having a stable, recent BIOS version helps compatibility."),
        ["energia"] = ("Power", "Shows the Windows power plan and its settings, such as the minimum and maximum processor state and USB suspend. On a gaming desktop, the ideal is a plan that lets the processor reach its maximum when needed."),
        ["timers"] = ("System timers (BCD)", "These are advanced Windows boot options that control the internal clock. Most people do not need to change them, and the Windows default is usually best. The app only warns if something outside the default is forced."),
        ["seguranca"] = ("Virtualization, antivirus and services", "Gathers Windows security and virtualization features, the antivirus and background services. Some security features protect a lot but cost a little performance in games."),
        ["virtualizacao"] = ("Virtualization and core isolation (VBS / HVCI)", "Windows can use virtualization to protect the system core against malicious drivers. This increases security but can cost a few percent of performance in games, mainly on modest processors. It is a trade-off between security and speed."),
        ["antivirus"] = ("Antivirus", "The antivirus scans files in real time. Having two antiviruses active at the same time slows the PC and can cause conflicts. Ideally just one, active and with up-to-date signatures."),
        ["minifiltros"] = ("File system minifilters", "These are small drivers that sit between Windows and the disk, used by antivirus, backup and encryption. Each filter adds a small delay to reads and writes. Few filters, from programs you really use, is the ideal."),
        ["servicos_temporarios"] = ("Services and temporary files", "Shows Windows services running in the background, such as SysMain and search, and how much space temporary files take. Temporary files above about 500 MB can be safely cleaned."),
        ["processos"] = ("Processes, startup, network and audio", "Shows which programs are using the most processor and memory right now, what opens with Windows, and the network and audio adapters. Programs open in the background compete with the game for resources."),
        ["processos_cpu"] = ("Top CPU-using processes", "This is the list of programs using the most processor at the time of reading. At idle, the expected value is low. If something other than the game shows high, it is worth closing it before playing."),
        ["processos_ram"] = ("Top RAM-using processes", "This is the list of programs occupying the most memory right now. Browsers and launchers are usually at the top. Closing what you do not use frees RAM for the game."),
        ["inicializacao"] = ("Startup programs", "These are programs that open by themselves when Windows starts. Many of them sit there all the time using memory and processor. You can stop them from opening at startup without uninstalling anything."),
        ["rede_audio"] = ("Network and audio", "Lists the active network cards and sound devices. Virtual adapters, such as VPN ones, can add latency in some cases. The app only reports what it found."),
        ["eventos"] = ("Windows events", "Windows keeps a log of errors and warnings. The app looks in it for signs tied to stutter, such as video driver hangs, disk errors and unexpected shutdowns. No serious event in the last 7 days is the ideal."),
        ["erros_boot"] = ("Errors since boot", "These are the errors Windows has logged since the PC was turned on. Many are harmless, such as failures of services that do not affect games. The source and repetition of the error matter more than the count."),
        ["eventos_engasgos"] = ("Stutter-related events", "These are Windows events that are usually tied to hitches: the video driver restarting, disk errors, hardware errors and unexpected restarts. If they appear repeatedly, it is worth investigating the driver, cables, power and temperature."),
        ["analise"] = ("Platform analysis", "Cross-checks the parts of your PC to say where the limit is: BIOS configuration, motherboard, processor or graphics card. For each point, it says whether the fix is free or requires hardware."),
        ["cadeia_pcie"] = ("Graphics card PCIe chain", "The graphics card talks to the rest of the PC over a connection called PCIe. That connection depends on the card itself, the processor, the motherboard and the BIOS, and the final speed is that of the slowest link. Ideally the link reaches the generation all the parts support."),
        ["resizable_bar"] = ("Resizable BAR", "A feature that lets the processor access all of the graphics card's memory at once, instead of in small pieces. The gain is small and varies by game, from nothing to a few percent. It requires a compatible graphics card and processor and is turned on in the BIOS, together with Above 4G Decoding."),
        ["equilibrio"] = ("System balance", "Checks whether the processor and the graphics card suit each other. A very strong graphics card with a processor with few cores makes the processor the limit. In that case, capping FPS makes the game more stable."),
        ["upgrade"] = ("Upgrade path", "Suggests a part swap that brings a gain without replacing the motherboard, such as a better processor that fits the same socket. Always check the board manufacturer's compatibility list before buying."),
        ["fonte"] = ("Power supply (PSU)", "The power supply delivers power to all the parts. A weak one can make the PC shut down or restart in heavy games. The app estimates the maximum consumption and recommends a power supply with about 50% headroom."),
        ["dados_nvidia"] = ("NVIDIA driver data", "These are readings taken by the NVIDIA driver: VBIOS version, video memory, temperature, power, clocks and PCIe link. They help check whether the card is working as it should."),
        ["subsistema_grafico"] = ("Graphics subsystem", "Gathers Windows options that affect games: HAGS, Game DVR, Game Mode, MPO and windowed-game optimizations. Each one can help or hurt depending on the game and driver."),
        ["sensores"] = ("Sensors", "These are the meters for temperature, fan, voltage and power of the PC parts. Windows alone does not show, for example, the processor temperature; for that WinDiag reads HWiNFO or the LibreHardwareMonitor library. It is a single-instant reading: to see behavior in the game, use the capture."),
        ["fontes_sensores"] = ("Sensor sources", "Shows where the readings came from: HWiNFO open with Shared Memory Support, the embedded LibreHardwareMonitor library and the PawnIO driver, if you installed it. WinDiag only reads and does not download or install drivers. Without one of these sources, the CPU temperature is unavailable."),

        ["pcie"] = ("PCIe", "It is the \"road\" that connects the graphics card and NVMe SSDs to the rest of the PC. The newer the generation and the more lanes, the higher the speed. For games, what matters is the graphics card operating at the generation and width it supports."),
        ["pcie_geracao"] = ("PCIe generation", "The generation (Gen 3, Gen 4, Gen 5) is the speed of each lane of the PCIe road; each generation doubles the speed of the previous one. A Gen 4 card on a Gen 3 connection still works, but at half the link speed. At idle the link drops a generation to save power, which is normal."),
        ["pcie_linhas"] = ("PCIe lanes (x16, x8)", "Lanes are the strips of the PCIe road: x16 has 16 lanes and x8 has 8. Some entry-level graphics cards use x8 on purpose and that is normal. An x16 card working at x4 or x8, however, may indicate the wrong slot or a riser."),
        ["rebar"] = ("Resizable BAR (ReBAR)", "Lets the processor access all of the graphics card's memory at once. The gain in games is usually from none to a few percent. It is turned on in the BIOS, and Windows must be in UEFI mode."),
        ["hags"] = ("HAGS (hardware-accelerated GPU scheduling)", "Lets the graphics card organize its own work instead of depending on the processor. In some games it helps, in others it hurts, and the effect depends on the driver. It is not a universal fix; the driver default is usually good."),
        ["mpo"] = ("MPO (Multiplane Overlay)", "A Windows feature for drawing the image in layers. With several monitors at different refresh rates, it has been linked to flicker and stutter on some PCs. Disabling it is only worth it as a test if you have those symptoms."),
        ["game_dvr"] = ("Game DVR (Xbox capture)", "This is the Xbox Game Bar's background recording. It uses the graphics card and disk even when you do not use it. If you do not record clips with the Game Bar, the ideal is to leave it off."),
        ["modo_de_jogo"] = ("Game Mode", "A Windows function that gives priority to the game and reduces background activity during play. In general it is harmless and helps a little. The ideal is to leave it on."),
        ["vbs_hvci"] = ("VBS and Memory Integrity (HVCI)", "Windows protections that isolate the system core using virtualization. They increase security but can cost a few percent of performance in games. Turning them off reduces protection against malicious drivers, so it is your decision."),
        ["hypervisor"] = ("Hypervisor", "The layer that allows running virtual machines, such as WSL, Hyper-V and Sandbox. When it is active, Windows runs on top of it, which costs little performance. If you do not use virtual machines, you can go without it."),
        ["smart"] = ("S.M.A.R.T.", "The self-diagnosis every disk performs on itself. Counters such as bad and reallocated sectors show whether the disk is wearing out. The good value is zero pending sectors; any increase deserves a backup."),
        ["trim"] = ("TRIM", "A command that tells the SSD which areas are no longer in use, so it stays fast. Without TRIM, the SSD loses write speed over time. The good value is enabled, which is the Windows default."),
        ["dual_channel"] = ("Dual channel", "This is when two memory modules work together on separate channels, doubling the RAM transfer speed. With a single module, or two on the same channel, the memory works at half. It helps more on processors with few cores and on integrated graphics."),
        ["xmp"] = ("XMP / DOCP / EXPO", "The speed profile stored on the memory modules. Without turning it on in the BIOS, the RAM runs at base speed, slower than what you bought. Turning it on is free and usually safe, but requires a board and processor that allow it."),
        ["pagefile"] = ("Paging file (pagefile)", "A space on the disk that Windows uses when RAM is not enough. It is useful as a safety net, but much slower than memory. If pagefile usage is high during games, RAM is lacking."),
        ["compressao_memoria"] = ("Memory compression", "Windows can compress data in RAM to avoid using the disk. With little RAM, this helps avoid hitches. With plenty of spare RAM, it needlessly spends a bit of processor."),
        ["hard_faults"] = ("Hard faults (page faults)", "They happen when Windows has to fetch from the disk something that should be in RAM. A high, constant number during the game indicates a lack of memory and causes stutter. Short spikes when opening programs are normal."),
        ["dpc"] = ("DPC (driver latency)", "The time drivers take from the processor in short, urgent tasks. When this time is high, crackling sound and stutter appear. The expected value is well below 1% of processor time."),
        ["secure_boot_uefi"] = ("Secure Boot and UEFI", "UEFI is the modern way to start the PC, and Secure Boot is a protection that only lets signed systems start. Some features, such as Resizable BAR and certain anti-cheat games, require UEFI. Having UEFI on is expected on current PCs."),
        ["bios"] = ("BIOS", "The motherboard program that starts the PC and defines how the parts work. It is where XMP and Resizable BAR are turned on and the PCIe generation is adjusted. Updating the BIOS is only worth it when it solves a problem or enables a feature you need."),
        ["chipset"] = ("Chipset", "The set of motherboard chips that decides what it supports: PCIe generation, memory overclocking and number of ports. It limits what the processor can offer. It is in the board name, such as B450, B560 or X670."),
        ["vram"] = ("VRAM (video memory)", "The graphics card's memory, where the game textures live. When it fills up, the game fetches data from the PC's RAM and stutters. For 1080p, 8 GB is usually enough, and for higher resolutions more is better."),
        ["taxa_atualizacao"] = ("Refresh rate (Hz)", "How many times per second the monitor refreshes the image. A 144 Hz monitor only uses that rate if Windows is set to it. The good practice is to use the monitor's maximum rate at the resolution in use."),
        ["steam_hdd"] = ("Steam games on HDD", "An HDD is much slower than an SSD at accessing many small files, such as game files. This causes long loading screens and stutter. Steam lets you move the game to an SSD without reinstalling."),
        ["sysmain"] = ("SysMain (Superfetch)", "A Windows service that preloads frequently used programs. On an SSD the gain is small and, on some PCs, it causes disk usage. The app only reports the state; the Windows default is usually adequate."),
        ["hibernacao"] = ("Hibernation and Fast Startup", "Fast Startup makes \"Shut down\" save part of the system so it starts faster. Because of that, the PC can go days without truly restarting, and problems accumulate. \"Restart\" does a clean boot."),
        ["plano_energia"] = ("Power plan", "The set of settings that tells Windows how much power to save. On a gaming desktop, the ideal is High performance or Balanced without limiting the processor to less than 100%."),
        ["aspm"] = ("ASPM (PCIe link power saving)", "The function that reduces PCIe link power when idle. When returning from power saving, there can be a small delay. The effect is usually small; turning it off is an option for those who want to eliminate that variable."),
        ["usb_suspend"] = ("USB selective suspend", "Windows can turn off idle USB ports to save power. On some mice, keyboards and headsets this causes delays or disconnections. On a desktop, it can stay off without problems."),
        ["ventoinha"] = ("Fan", "Moves air to cool the parts. The speed rises with temperature, and that is normal. If the graphics card fan is stopped at idle, it is usually the manufacturer's silent mode."),
        ["temperatura"] = ("Temperature", "Parts heat up under load and reduce their own speed when they get too hot. For the graphics card and processor, below 80 °C in game is comfortable and above 90 °C deserves attention. Disks should stay below about 55 °C."),
        ["psu"] = ("Power supply (PSU)", "The power supply converts wall power for the parts. What matters is having headroom in wattage and good quality, not just the number of watts. A power supply at its limit can cause restarts under load."),
        ["tdp"] = ("TDP and power limit", "TDP is the processor's reference power, and the power limit is the maximum the graphics card may draw. The app uses these numbers to estimate the power supply needed. In turbo peaks, real consumption goes above the TDP."),
        ["throttling"] = ("Clock throttling", "This is when a part reduces its own speed so as not to exceed a temperature, power or voltage limit. It shows up as an FPS drop under load. If it happens all the time, it is worth reviewing the cooling."),
        ["hpet"] = ("HPET and system clock", "HPET is an old motherboard clock. Forcing its use in Windows can increase latency in games. The Windows default, without forcing, is the recommended one."),
        ["nucleos_threads"] = ("Cores and threads", "Cores are the processor's work units, and threads are the tasks each core can handle at the same time. Modern games use 6 or more cores well. With 4 cores, background programs compete with the game."),
        ["frametime"] = ("FPS and frametime", "FPS is the average frames per second, and frametime is the time of each frame. A high FPS with irregular frametime feels like stutter. Stability matters as much as the average."),
        ["tipos_disco"] = ("HDD, SSD and NVMe", "An HDD has moving parts and is slow. An SSD uses flash memory and is much faster, and NVMe is the SSD that connects directly to PCIe, faster still. For games and Windows, an SSD already makes a big difference."),
        ["uptime"] = ("Uptime", "How long the PC has been on since the last real boot. Many days without restarting can accumulate driver problems. Restarting from time to time keeps Windows stable."),
        ["tdr"] = ("TDR (video driver restarted)", "This is when Windows restarts the video driver because the card stopped responding. The screen flickers or goes black for a moment. If it repeats, it may be the driver, power, temperature or overclocking."),
        ["whea"] = ("WHEA (hardware errors)", "The log of hardware errors detected by the processor, such as memory or PCIe bus failures. Occasional corrected errors can be normal. If they are frequent, they indicate instability."),
        ["crc_sata"] = ("SATA CRC errors", "They indicate communication failures between the disk and the motherboard, almost always from a bad or poorly seated cable. The counter only goes up. What matters is whether it keeps increasing after replacing the cable."),
        ["setores_ruins"] = ("Reallocated and pending sectors", "These are pieces of the disk that stopped working. Few and stable ones are tolerated; pending or growing ones indicate wear and a risk of data loss. In that case, make a backup."),
        ["wsl_vm"] = ("WSL and virtual machines", "WSL and virtual machines reserve part of the RAM for themselves while active. They appear as the vmmem process. Closing the owning application frees the memory for the game."),
        ["atlasos"] = ("AtlasOS", "A modified version of Windows that already applies several performance tweaks. That is why WinDiag avoids reapplying tweaks on top, to prevent conflicts."),
        ["above_4g"] = ("Above 4G Decoding", "A BIOS option that lets the PC address more than 4 GB of memory for devices. It is a prerequisite for Resizable BAR. It must be on together with it."),
        ["csm"] = ("CSM (legacy mode)", "A BIOS compatibility mode that imitates old PCs. With it on, Windows starts in legacy mode and Resizable BAR does not work. On current PCs, the ideal is CSM off and UEFI boot."),
        ["overclock_memoria"] = ("Memory overclocking", "Running the RAM faster than the processor's default. XMP is the simplest way and is done by the memory manufacturer. Not every chipset allows it."),
        ["estado_processador"] = ("Processor state (min / max)", "The limit the power plan places on processor usage. The maximum should be 100% so the processor can use its full turbo. Lower values reduce performance in games."),
        ["game_bar"] = ("Xbox Game Bar", "The Windows layer with capture shortcuts and overlays. When it keeps recording in the background, it uses resources. You can disable capture without losing the rest."),
    };
}
